import os
import re
import json
from pathlib import Path
import pytesseract
from PIL import Image, ImageOps
import openpyxl

IMG_DIR = Path('/app/workspace/dataset/img')
CACHE_DIR = Path('/app/workspace/ocr_cache')
CACHE_DIR.mkdir(exist_ok=True)
OUT = Path('/app/workspace/stat_ocr.xlsx')

PRIORITY_GROUPS = [
    ['GRAND TOTAL'],
    ['TOTAL RM', 'TOTAL: RM'],
    ['TOTAL AMOUNT'],
    ['TOTAL', 'AMOUNT', 'TOTAL DUE', 'AMOUNT DUE', 'BALANCE DUE', 'NETT TOTAL', 'NET TOTAL'],
]
EXCLUSIONS = ['SUBTOTAL', 'SUB TOTAL', 'TAX', 'GST', 'SST', 'DISCOUNT', 'CHANGE', 'CASH TENDERED']

# Capture numeric tokens that may contain . or , as internal separators.
AMOUNT_RE = re.compile(r'(?<![\d])(\d[\d.,]*\d|\d)(?![\d])')


def ocr_text(path: Path) -> str:
    cache = CACHE_DIR / (path.stem + '.txt')
    if cache.exists():
        return cache.read_text()
    img = Image.open(path)
    g = ImageOps.grayscale(img)
    g = ImageOps.autocontrast(g)
    try:
        txt = pytesseract.image_to_string(g, config='--psm 6', timeout=60)
    except Exception:
        txt = ''
    cache.write_text(txt)
    return txt


def _parse_num_token(tok: str):
    """Interpret a token like '1,234.56', '99,80', '538', '702.00' as float."""
    if not tok:
        return None
    tok = tok.strip('.,')
    if not tok or not any(c.isdigit() for c in tok):
        return None
    has_dot = '.' in tok
    has_comma = ',' in tok
    if has_dot and has_comma:
        # Last separator is decimal; others are thousand separators
        last_dot = tok.rfind('.')
        last_comma = tok.rfind(',')
        if last_dot > last_comma:
            tok = tok.replace(',', '')
        else:
            # last comma is decimal
            tok = tok.replace('.', '').replace(',', '.')
    elif has_comma:
        parts = tok.split(',')
        # If exactly one comma and 1-2 digits after -> decimal
        if len(parts) == 2 and 1 <= len(parts[1]) <= 2:
            tok = tok.replace(',', '.')
        else:
            tok = tok.replace(',', '')
    # else: has_dot or just digits — leave as-is
    try:
        return float(tok)
    except ValueError:
        return None


def _format_amount(v):
    if v is None:
        return None
    return f"{v:.2f}"


def extract_amounts(s: str):
    """Return list of (float, token_str) found in s."""
    out = []
    for m in AMOUNT_RE.finditer(s):
        tok = m.group(1)
        v = _parse_num_token(tok)
        if v is not None:
            out.append(v)
    return out


def _normalize_for_match(u: str) -> str:
    """Replace non-alphanumerics with single spaces for keyword/exclusion matching."""
    return re.sub(r'[^A-Z0-9]+', ' ', u)


def find_total(text: str):
    raw_lines = [l.rstrip() for l in text.splitlines()]
    # Preprocess each line: for same-line amount extraction, repair "N N2" (space-separated two-digit decimal)
    norm_up = [_normalize_for_match(l.upper()) for l in raw_lines]

    def line_excluded(nu):
        return any(k in nu for k in EXCLUSIONS)

    for group in PRIORITY_GROUPS:
        candidates = []       # list of (i, amount) for lines with same-line amount
        no_amount_lines = []  # lines that match keyword but have no numeric amount
        for i, nu in enumerate(norm_up):
            if line_excluded(nu):
                continue
            if not any(k in nu for k in group):
                continue
            line = raw_lines[i]
            # Try to extract amount from the portion AFTER the keyword (last keyword occurrence).
            # Use the normalized string for keyword position but map back via substring search in uppercase.
            up_line = line.upper()
            # Determine the rightmost keyword position in the original (upper) line.
            best_end = -1
            for k in group:
                # Try matching against normalized version by scanning original with regex of keyword where spaces match any non-alnum
                kp = re.compile(re.escape(k).replace(r'\ ', r'[^A-Z0-9]+'))
                for m in kp.finditer(up_line):
                    if m.end() > best_end:
                        best_end = m.end()
            tail = line[best_end:] if best_end >= 0 else line
            # Repair spaced decimals like "538 00" at end of tail
            tail_fixed = re.sub(r'(\d+)\s+(\d{2})(?!\d)', r'\1.\2', tail)
            amounts = extract_amounts(tail_fixed)
            if amounts:
                # The total value on a line is typically the last number
                candidates.append((i, amounts[-1]))
                continue
            # Try the whole line (keyword may be at end)
            full_fixed = re.sub(r'(\d+)\s+(\d{2})(?!\d)', r'\1.\2', line)
            amounts = extract_amounts(full_fixed)
            if amounts:
                candidates.append((i, amounts[-1]))
                continue
            no_amount_lines.append(i)
        if candidates:
            # Prefer the LAST candidate line (totals usually near the bottom)
            return _format_amount(candidates[-1][1])
        # Fallback: look at the next non-empty line of a header-only match
        for i in no_amount_lines:
            for j in range(i + 1, min(i + 3, len(raw_lines))):
                nxt = raw_lines[j]
                if not nxt.strip():
                    continue
                nxt_fixed = re.sub(r'(\d+)\s+(\d{2})(?!\d)', r'\1.\2', nxt)
                nums = extract_amounts(nxt_fixed)
                if nums:
                    return _format_amount(nums[-1])
                break
    return None


DATE_PATTERNS = [
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{4})'), 'dmy'),
    (re.compile(r'(\d{4})[/\-.](\d{1,2})[/\-.](\d{1,2})'), 'ymd'),
    (re.compile(r'(\d{1,2})[/\-.](\d{1,2})[/\-.](\d{2})(?!\d)'), 'dmy2'),
    (re.compile(r'(\d{1,2})[\s\-]+(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*[\s\-,]+(\d{4})', re.I), 'dMy'),
    (re.compile(r'(JAN|FEB|MAR|APR|MAY|JUN|JUL|AUG|SEP|SEPT|OCT|NOV|DEC)[A-Z]*[\s\-]+(\d{1,2})[\s\-,]+(\d{4})', re.I), 'Mdy'),
]
MONTHS = {'JAN': 1, 'FEB': 2, 'MAR': 3, 'APR': 4, 'MAY': 5, 'JUN': 6,
          'JUL': 7, 'AUG': 8, 'SEP': 9, 'SEPT': 9, 'OCT': 10, 'NOV': 11, 'DEC': 12}


def find_date(text: str):
    for pat, kind in DATE_PATTERNS:
        for m in pat.finditer(text):
            try:
                if kind == 'dmy':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'ymd':
                    y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
                elif kind == 'dmy2':
                    d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3)) + 2000
                elif kind == 'dMy':
                    d = int(m.group(1))
                    mo = MONTHS[m.group(2).upper()[:3]]
                    y = int(m.group(3))
                elif kind == 'Mdy':
                    mo = MONTHS[m.group(1).upper()[:3]]
                    d = int(m.group(2))
                    y = int(m.group(3))
                if not (1 <= mo <= 12 and 1 <= d <= 31 and 1990 <= y <= 2099):
                    continue
                return f"{y:04d}-{mo:02d}-{d:02d}"
            except Exception:
                continue
    return None


def main():
    files = sorted([p for p in IMG_DIR.iterdir() if p.suffix.lower() in {'.jpg', '.jpeg', '.png'}])
    rows = []
    for p in files:
        txt = ocr_text(p)
        date = find_date(txt)
        total = find_total(txt)
        rows.append((p.name, date, total))
        print(p.name, date, total)

    wb = openpyxl.Workbook()
    ws = wb.active
    ws.title = 'results'
    ws.append(['filename', 'date', 'total_amount'])
    for name, date, total in rows:
        ws.append([name, date, total])
    wb.save(OUT)

    wb2 = openpyxl.load_workbook(OUT)
    assert wb2.sheetnames == ['results']
    ws2 = wb2['results']
    header = [c.value for c in ws2[1]]
    assert header == ['filename', 'date', 'total_amount'], header
    assert ws2.max_row == len(rows) + 1
    print(f"schema OK: {OUT} rows={ws2.max_row - 1}")


if __name__ == '__main__':
    main()
